command.py:
"""Explicit command oracle protocol. Process limits are not a security sandbox."""

from __future__ import annotations

import json
import math
import os
import signal
import subprocess
import tempfile
import time
from collections.abc import Sequence
from contextlib import suppress
from pathlib import Path

from .model import Event, Outcome, Trace


def _unique(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate outcome key")
        result[key] = value
    return result


class CommandOracle:
    """Run argv with {trace} replaced by a temporary candidate JSON path.

    Stdout must be one JSON Outcome object. Nonzero exit, timeout, excess output,
    and malformed protocol are UNRESOLVED, never evidence of the target failure.
    On POSIX a separate process group is killed after each invocation, including
    successfully exited parents. Windows cleanup covers the direct process only.
    """

    def __init__(
        self,
        argv: Sequence[str],
        *,
        timeout: float = 10,
        max_output_bytes: int = 1_000_000,
        cwd: str | Path | None = None,
    ) -> None:
        if isinstance(argv, str) or not argv or not all(isinstance(arg, str) for arg in argv):
            raise ValueError("argv must be a nonempty sequence of strings")
        if not any("{trace}" in arg for arg in argv):
            raise ValueError("command must include a {trace} placeholder")
        if isinstance(timeout, bool) or not math.isfinite(timeout) or timeout <= 0:
            raise ValueError("timeout must be finite and positive")
        if type(max_output_bytes) is not int or max_output_bytes < 1:
            raise ValueError("max_output_bytes must be positive")
        self.argv = tuple(argv)
        self.timeout = timeout
        self.max_output_bytes = max_output_bytes
        self.cwd = cwd

    def __call__(self, events: tuple[Event, ...]) -> Outcome:
        with tempfile.TemporaryDirectory(prefix="casecrop-") as directory:
            trace_path = Path(directory) / "candidate.json"
            Trace(events).save(trace_path)
            argv = [arg.replace("{trace}", str(trace_path)) for arg in self.argv]
            with tempfile.TemporaryFile() as output, tempfile.TemporaryFile() as errors:
                process = subprocess.Popen(
                    argv,
                    cwd=self.cwd,
                    stdout=output,
                    stderr=errors,
                    stdin=subprocess.DEVNULL,
                    start_new_session=os.name == "posix",
                )
                stop = ""
                deadline = time.monotonic() + self.timeout
                try:
                    while process.poll() is None:
                        if (
                            os.fstat(output.fileno()).st_size + os.fstat(errors.fileno()).st_size
                            > self.max_output_bytes
                        ):
                            stop = "command output limit exceeded"
                            break
                        if time.monotonic() >= deadline:
                            stop = "command timed out"
                            break
                        time.sleep(0.01)
                finally:
                    if os.name == "posix":
                        with suppress(ProcessLookupError):
                            os.killpg(process.pid, signal.SIGKILL)
                    elif process.poll() is None:
                        process.kill()
                    process.wait()
                if (
                    os.fstat(output.fileno()).st_size + os.fstat(errors.fileno()).st_size
                    > self.max_output_bytes
                ):
                    stop = "command output limit exceeded"
                if stop:
                    return Outcome.unresolved(stop)
                if process.returncode != 0:
                    return Outcome.unresolved("command exited unsuccessfully")
                output.seek(0)
                try:
                    data = json.loads(
                        output.read(self.max_output_bytes).decode("utf-8"),
                        object_pairs_hook=_unique,
                    )
                    if not isinstance(data, dict) or set(data) - {"verdict", "signature", "reason"}:
                        raise ValueError("invalid outcome")
                    return Outcome(**data)
                except (ValueError, TypeError, UnicodeError, RecursionError):
                    return Outcome.unresolved("command returned invalid outcome JSON")

examples.py:
"""Small stateful systems with actual defects and corrected implementations."""

from __future__ import annotations

from typing import Any

from .model import Event, Outcome, Trace
from .reducer import Result, minimize

CASES = {
    "cache": {
        "title": "The cache that forgot who you are",
        "signature": "cache.cross_tenant",
        "description": "Two tenants. One resource ID. A cache key missing its tenant.",
        "fix": "Include the tenant ID in every cache key.",
    },
    "counter": {
        "title": "Two workers. One missing update.",
        "signature": "counter.lost_update",
        "description": "Both workers read 0. Both write 1. Two increments become one.",
        "fix": "Apply an atomic increment instead of writing a stale snapshot.",
    },
    "permission": {
        "title": "The permission that wouldn't leave",
        "signature": "auth.stale_allow",
        "description": "Access was revoked. The cached permission didn't get the memo.",
        "fix": "Invalidate the permission cache when grants change.",
    },
}


def make_trace(case: str = "cache", noise: int = 30) -> Trace:
    if case not in CASES:
        raise ValueError("unknown case")
    if type(noise) is not int or not 0 <= noise <= 500:
        raise ValueError("noise must be an integer between 0 and 500")
    if case == "cache":
        important = [
            Event("tenant-a", {"op": "tenant", "tenant": "acme"}),
            Event("tenant-b", {"op": "tenant", "tenant": "nova"}),
            Event(
                "store-a",
                {"op": "put", "tenant": "acme", "key": "invoice-7", "value": "ACME PRIVATE"},
                requires=("tenant-a",),
            ),
            Event(
                "store-b",
                {"op": "put", "tenant": "nova", "key": "invoice-7", "value": "NOVA PRIVATE"},
                requires=("tenant-b",),
            ),
            Event(
                "read-a", {"op": "get", "tenant": "acme", "key": "invoice-7"}, requires=("store-a",)
            ),
            Event(
                "read-b", {"op": "get", "tenant": "nova", "key": "invoice-7"}, requires=("store-b",)
            ),
        ]
    elif case == "counter":
        important = [
            Event("init", {"op": "init", "value": 0}),
            Event("read-a", {"op": "read", "worker": "a"}, requires=("init",)),
            Event("read-b", {"op": "read", "worker": "b"}, requires=("init",)),
            Event("write-a", {"op": "increment", "worker": "a"}, requires=("read-a",)),
            Event("write-b", {"op": "increment", "worker": "b"}, requires=("read-b",)),
        ]
    else:
        important = [
            Event("grant", {"op": "grant", "user": "alex"}),
            Event("check-a", {"op": "check", "user": "alex"}, requires=("grant",)),
            Event("revoke", {"op": "revoke", "user": "alex"}, requires=("grant",)),
            Event("check-b", {"op": "check", "user": "alex"}, requires=("grant",)),
        ]
    # Independent observations interleaved with the bug's state transitions.
    events = []
    for index, event in enumerate(important):
        events.append(event)
        for j in range(index, noise, len(important)):
            events.append(
                Event(
                    f"log-{j:03}",
                    {
                        "op": "observe",
                        "metric": ["latency", "health", "tokens", "queue_depth"][j % 4],
                        "value": j * 7 + 3,
                    },
                    cost=2,
                )
            )
    return Trace(events)


def replay(case: str, events: tuple[Event, ...], *, fixed: bool = False) -> Outcome:
    """Fresh state per invocation. The selected implementation performs every operation."""
    if case not in CASES:
        raise ValueError("unknown case")
    tenants: set[str] = set()
    storage: dict[tuple[str, str], Any] = {}
    cache: dict[Any, Any] = {}
    counter: int | None = None
    increments = 0
    initial = 0
    reads: dict[str, int] = {}
    grants: dict[str, bool] = {}
    for event in events:
        payload = event.payload
        if not isinstance(payload, dict) or not isinstance(payload.get("op"), str):
            return Outcome.unresolved("event payload needs an op")
        op = payload["op"]
        if op == "observe":
            continue
        try:
            if case == "cache":
                tenant = payload["tenant"]
                if not isinstance(tenant, str):
                    return Outcome.unresolved("tenant must be a string")
                if op == "tenant":
                    tenants.add(tenant)
                    continue
                if tenant not in tenants:
                    return Outcome.unresolved("tenant missing")
                key = payload["key"]
                if not isinstance(key, str):
                    return Outcome.unresolved("key must be a string")
                identity = (tenant, key)
                cache_key = identity if fixed else key
                if op == "put":
                    storage[identity] = payload["value"]
                    cache.pop(cache_key, None)
                elif op == "get":
                    if identity not in storage:
                        return Outcome.unresolved("resource missing")
                    if cache_key not in cache:
                        cache[cache_key] = storage[identity]
                    if cache[cache_key] != storage[identity]:
                        return Outcome.fail("cache.cross_tenant")
                else:
                    return Outcome.unresolved("unknown cache operation")
            elif case == "counter":
                if op == "init":
                    if type(payload["value"]) is not int:
                        return Outcome.unresolved("initial value must be an integer")
                    initial = counter = payload["value"]
                    increments = 0
                    reads.clear()
                elif op in ("read", "increment"):
                    worker = payload["worker"]
                    if not isinstance(worker, str) or counter is None:
                        return Outcome.unresolved("worker or counter missing")
                    if op == "read":
                        reads[worker] = counter
                    else:
                        if worker not in reads:
                            return Outcome.unresolved("worker snapshot missing")
                        counter = counter + 1 if fixed else reads[worker] + 1
                        increments += 1
                        if counter != initial + increments:
                            return Outcome.fail("counter.lost_update")
                else:
                    return Outcome.unresolved("unknown counter operation")
            else:
                user = payload["user"]
                if not isinstance(user, str):
                    return Outcome.unresolved("user must be a string")
                if op in ("grant", "revoke"):
                    grants[user] = op == "grant"
                    if fixed:
                        cache.pop(user, None)
                elif op == "check":
                    if user not in grants:
                        return Outcome.unresolved("user missing")
                    if user not in cache:
                        cache[user] = grants[user]
                    if cache[user] and not grants[user]:
                        return Outcome.fail("auth.stale_allow")
                else:
                    return Outcome.unresolved("unknown permission operation")
        except KeyError:
            return Outcome.unresolved("operation is missing a required field")
    return Outcome.pass_()


def demo(
    case: str = "cache",
    *,
    noise: int = 30,
    max_calls: int = 500,
    repeats: int = 1,
    trace: Trace | None = None,
) -> Result:
    return minimize(
        trace if trace is not None else make_trace(case, noise),
        lambda events: replay(case, events),
        max_calls=max_calls,
        repeats=repeats,
        signature=CASES[case]["signature"],
        oracle_id=f"casecrop.{case}.buggy-v1",
    )


def browser_run(request_json: str) -> str:
    """Bounded bridge used by the real Python Web Worker, never a TypeScript reimplementation."""
    import json

    request = json.loads(request_json)
    if not isinstance(request, dict):
        raise ValueError("browser request must be an object")
    case = request.get("case", "cache")
    budget = request.get("max_calls", 500)
    repeats = request.get("repeats", 1)
    if type(budget) is not int or not 1 <= budget <= 2000:
        raise ValueError("call budget must be between 1 and 2000")
    if type(repeats) is not int or not 1 <= repeats <= 3:
        raise ValueError("repeats must be between 1 and 3")
    trace = Trace.from_dict(request["trace"]) if "trace" in request else None
    if "trace_json" in request:
        raw = request["trace_json"]
        if not isinstance(raw, str) or len(raw.encode("utf-8")) > 256_000:
            raise ValueError("browser trace JSON must be a string of at most 256 KB")
        trace = Trace.from_json(raw)

    def browser_numbers(value: Any) -> None:
        if type(value) is int and abs(value) > 9_007_199_254_740_991:
            raise ValueError(
                "browser integers must be within the JavaScript safe range; use Python"
            )
        if isinstance(value, dict):
            for item in value.values():
                browser_numbers(item)
        elif isinstance(value, list):
            for item in value:
                browser_numbers(item)

    if trace is not None:
        browser_numbers(trace.to_dict())
    if trace is not None and len(trace.events) > 200:
        raise ValueError("browser traces are limited to 200 events; use Python for larger traces")
    result = demo(
        case, noise=request.get("noise", 30), max_calls=budget, repeats=repeats, trace=trace
    )
    value = result.to_dict()
    value["fixed_outcome"] = replay(case, result.reduced.events, fixed=True).to_dict()
    value["reduced_json"] = result.reduced.to_json()
    value["original_json"] = result.original.to_json()
    return json.dumps(value)

model.py:
"""Portable, validated data structures. No code is loaded from trace files."""

from __future__ import annotations

import hashlib
import json
import math
from collections.abc import Iterable
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Literal

MAX_EVENTS = 10_000
MAX_BYTES = 8_000_000
Verdict = Literal["fail", "pass", "unresolved"]


def canonical(value: Any) -> str:
    """Validate JSON without lossy key/type coercion, then encode canonically."""

    def check(item: Any, depth: int = 0) -> None:
        if depth > 64:
            raise ValueError("JSON nesting exceeds 64 levels")
        if item is None or type(item) in (str, bool, int):
            return
        if type(item) is float and math.isfinite(item):
            return
        if type(item) is list:
            for child in item:
                check(child, depth + 1)
            return
        if type(item) is dict and all(type(key) is str for key in item):
            for child in item.values():
                check(child, depth + 1)
            return
        raise ValueError("Payloads must contain finite JSON values with string object keys")

    check(value)
    encoded = json.dumps(value, sort_keys=True, ensure_ascii=True, separators=(",", ":"))
    if len(encoded) > MAX_BYTES:
        raise ValueError("JSON exceeds 8 MB")
    return encoded


def _text(value: Any, name: str, limit: int = 200) -> str:
    if not isinstance(value, str) or not value.strip() or len(value) > limit:
        raise ValueError(f"{name} must be a nonempty string of at most {limit} characters")
    return value


@dataclass(frozen=True, init=False)
class Event:
    """An immutable event with a detached JSON payload and earlier prerequisites."""

    id: str
    _payload_json: str
    requires: tuple[str, ...]
    pinned: bool
    cost: int

    def __init__(
        self,
        id: str,
        payload: Any = None,
        *,
        requires: Iterable[str] = (),
        pinned: bool = False,
        cost: int = 1,
    ) -> None:
        _text(id, "event id")
        if isinstance(requires, str):
            raise ValueError("requires must be a sequence of event IDs, not a string")
        deps = tuple(requires)
        for dep in deps:
            _text(dep, "dependency id")
        if len(set(deps)) != len(deps):
            raise ValueError("duplicate dependency")
        if type(pinned) is not bool:
            raise ValueError("pinned must be a boolean")
        if type(cost) is not int or cost < 1:
            raise ValueError("cost must be a positive integer")
        object.__setattr__(self, "id", id)
        object.__setattr__(self, "_payload_json", canonical(payload))
        object.__setattr__(self, "requires", deps)
        object.__setattr__(self, "pinned", pinned)
        object.__setattr__(self, "cost", cost)

    @property
    def payload(self) -> Any:
        """A new value on every access: an oracle cannot mutate the source trace."""
        return json.loads(self._payload_json)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "payload": self.payload,
            "requires": list(self.requires),
            "pinned": self.pinned,
            "cost": self.cost,
        }

    @classmethod
    def from_dict(cls, value: Any) -> Event:
        if not isinstance(value, dict) or "id" not in value:
            raise ValueError("each event must be an object with an id")
        if set(value) - {"id", "payload", "requires", "pinned", "cost"}:
            raise ValueError("unknown event fields")
        if not isinstance(value.get("requires", []), list):
            raise ValueError("requires must be an array")
        return cls(
            value["id"],
            value.get("payload"),
            requires=value.get("requires", []),
            pinned=value.get("pinned", False),
            cost=value.get("cost", 1),
        )


@dataclass(frozen=True, init=False)
class Trace:
    events: tuple[Event, ...]

    def __init__(self, events: Iterable[Event]) -> None:
        items = tuple(events)
        if len(items) > MAX_EVENTS:
            raise ValueError(f"trace exceeds {MAX_EVENTS} events")
        seen: set[str] = set()
        for event in items:
            if not isinstance(event, Event):
                raise TypeError("trace entries must be Event objects")
            if event.id in seen:
                raise ValueError(f"duplicate event id: {event.id}")
            if not set(event.requires) <= seen:
                raise ValueError(f"{event.id}: prerequisites must exist before the event")
            seen.add(event.id)
        object.__setattr__(self, "events", items)
        canonical(self.to_dict())

    @property
    def ids(self) -> tuple[str, ...]:
        return tuple(event.id for event in self.events)

    @property
    def cost(self) -> int:
        return sum(event.cost for event in self.events)

    @property
    def digest(self) -> str:
        return hashlib.sha256(canonical(self.to_dict()).encode()).hexdigest()

    def to_dict(self) -> dict[str, Any]:
        return {"schema_version": 1, "events": [e.to_dict() for e in self.events]}

    def to_json(self) -> str:
        return canonical(self.to_dict())

    @classmethod
    def from_dict(cls, value: Any) -> Trace:
        if not isinstance(value, dict) or set(value) != {"schema_version", "events"}:
            raise ValueError("trace requires exactly schema_version and events")
        if type(value["schema_version"]) is not int or value["schema_version"] != 1:
            raise ValueError("unsupported trace schema_version")
        if not isinstance(value["events"], list):
            raise ValueError("events must be an array")
        return cls(Event.from_dict(event) for event in value["events"])

    @classmethod
    def from_json(cls, value: str) -> Trace:
        if len(value.encode("utf-8")) > MAX_BYTES:
            raise ValueError("trace exceeds 8 MB")

        def unique(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
            result: dict[str, Any] = {}
            for key, item in pairs:
                if key in result:
                    raise ValueError(f"duplicate JSON key: {key}")
                result[key] = item
            return result

        return cls.from_dict(json.loads(value, object_pairs_hook=unique))

    @classmethod
    def load(cls, path: str | Path) -> Trace:
        with Path(path).open("rb") as stream:
            data = stream.read(MAX_BYTES + 1)
        if len(data) > MAX_BYTES:
            raise ValueError("trace exceeds 8 MB")
        return cls.from_json(data.decode("utf-8"))

    def save(self, path: str | Path) -> None:
        Path(path).write_text(self.to_json(), encoding="utf-8")


@dataclass(frozen=True)
class Outcome:
    verdict: Verdict
    signature: str = ""
    reason: str = ""

    def __post_init__(self) -> None:
        if self.verdict not in ("fail", "pass", "unresolved"):
            raise ValueError("verdict must be fail, pass, or unresolved")
        if not isinstance(self.signature, str) or len(self.signature) > 200:
            raise ValueError("signature must be a string of at most 200 characters")
        if not isinstance(self.reason, str) or len(self.reason) > 2000:
            raise ValueError("reason must be a string of at most 2000 characters")
        if self.verdict == "fail":
            _text(self.signature, "failure signature")
        elif self.signature:
            raise ValueError("only fail outcomes have a signature")

    @classmethod
    def fail(cls, signature: str) -> Outcome:
        return cls("fail", signature)

    @classmethod
    def pass_(cls) -> Outcome:
        return cls("pass")

    @classmethod
    def unresolved(cls, reason: str = "") -> Outcome:
        return cls("unresolved", reason=reason)

    def to_dict(self) -> dict[str, str]:
        return {"verdict": self.verdict, "signature": self.signature, "reason": self.reason}
